WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM sessions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT s.id, s.customer_id, s.device, s.started_at, s.country, s.session_start_flag, (SELECT SUM(t2.amount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_amount FROM sessionized s
